-- Table: accounting_period
-- Source: accounting_admin_db.sql (2. Accounting core and budget)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS accounting_period (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    period_code VARCHAR(7)  NOT NULL UNIQUE,
    start_date  DATE        NOT NULL,
    end_date    DATE        NOT NULL,
    status      VARCHAR(20) NOT NULL DEFAULT 'open'
                CHECK (status IN ('open', 'closed')),
    closed_by   BIGINT REFERENCES masterdata_user(id),
    closed_at   TIMESTAMPTZ,
    notes       TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (start_date <= end_date)
);
